+    private ValidationResult validateEmail(String email, ValueContext ctx) {
+        if (email == null || email.isEmpty()) {
+            if (phoneField.isEmpty()) {
+                return ValidationResult.error("Give an e-mail address or a phone number");
+            }
+            return ValidationResult.ok();
+        }
+
