+
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+        binder.readBean(new FormData());
+
+        sendButton.setEnabled(false);
+        shouldWarnOnLeave = false;
+
+        Notification.show("Message sent");
+        refreshGrid();
+    }
+
